///////////////////////////////////////////
// dcache1.S
//
// Written: avercruysse@hmc.edu 18 April 2023
//
// Purpose: Test coverage for D$: for each way, trigger a CacheDataMem write enable while chip enable
//          is low, then flush each way's line with cbo.flush.  The four way tests were generated by
//          dcache1.py; the flushes and the checks were added by hand afterwards.
//          Each way test stores two different values to its line, all four lines in the same set.
//          The cbo.flush instructions write the lines back and invalidate them, so reading them
//          afterwards fetches them from memory and checks both the second store and the writebacks.
//          Finally five lines of one set, one more than the ways, are stored and read back, so the
//          lines are evicted and refetched, and every value must survive.
//
// A component of the CORE-V-WALLY configurable RISC-V project.
// https://github.com/openhwfoundation/cvw
//
// Copyright (C) 2021-26 Harvey Mudd College & Oklahoma State University
//
// SPDX-License-Identifier: Apache-2.0 WITH SHL-2.1
////////////////////////////////////////////////////////////////////////////////////////////////

      #include "WALLY-init-lib.h"
      #include "WALLY-selfcheck.h"
main:
      // Values stored by the way tests: the first store of way test n stores s(2n), the second s(2n+1)
      li s2, 0x1111111111111111
      li s3, 0x2222222222222222
      li s4, 0x3333333333333333
      li s5, 0x4444444444444444
      li s6, 0x5555555555555555
      li s7, 0x6666666666666666
      li s8, 0x7777777777777777
      li s9, 0x8888888888888888
      // start way test #1
      li t0, 0x80100000
.align 6
      // i$ boundary, way test #1
      .word 0x00000013
      .word 0x00000013
      .word 0x00000013
      .word 0x00000013
      .word 0x00000013
      .word 0x00000013
      .word 0x00000013
      .word 0x00000013
      .word 0x00000013
      .word 0x00000013
      .word 0x00000013
      .word 0x00000013
      sd s2, 0(t0)
      sd s3, 0(t0)
      .word 0x00000013
      .word 0x00000013
      // start way test #2
      li t0, 0x80101000
.align 6
      // i$ boundary, way test #2
      .word 0x00000013
      .word 0x00000013
      .word 0x00000013
      .word 0x00000013
      .word 0x00000013
      .word 0x00000013
      .word 0x00000013
      .word 0x00000013
      .word 0x00000013
      .word 0x00000013
      .word 0x00000013
      .word 0x00000013
      sd s4, 0(t0)
      sd s5, 0(t0)
      .word 0x00000013
      .word 0x00000013
      // start way test #3
      li t0, 0x80102000
.align 6
      // i$ boundary, way test #3
      .word 0x00000013
      .word 0x00000013
      .word 0x00000013
      .word 0x00000013
      .word 0x00000013
      .word 0x00000013
      .word 0x00000013
      .word 0x00000013
      .word 0x00000013
      .word 0x00000013
      .word 0x00000013
      .word 0x00000013
      sd s6, 0(t0)
      sd s7, 0(t0)
      .word 0x00000013
      .word 0x00000013
      // start way test #4
      li t0, 0x80103000
.align 6
      // i$ boundary, way test #4
      .word 0x00000013
      .word 0x00000013
      .word 0x00000013
      .word 0x00000013
      .word 0x00000013
      .word 0x00000013
      .word 0x00000013
      .word 0x00000013
      .word 0x00000013
      .word 0x00000013
      .word 0x00000013
      .word 0x00000013
      sd s8, 0(t0)
      sd s9, 0(t0)
      .word 0x00000013
      .word 0x00000013

# test flushing
      li t0, 0x80100000
      cbo.flush (t0)
      li t0, 0x80101000
      cbo.flush (t0)
      li t0, 0x80102000
      cbo.flush (t0)
      li t0, 0x80103000
      cbo.flush (t0)

# The flushed lines are no longer in the cache, so these loads read memory: each must return the
# second value its way test stored
      li a1, 0x80100000
      ld a0, 0(a1)
      SC_CHECK_EQ_ADR a0, s3, a1, 1
      li a1, 0x80101000
      ld a0, 0(a1)
      SC_CHECK_EQ_ADR a0, s5, a1, 2
      li a1, 0x80102000
      ld a0, 0(a1)
      SC_CHECK_EQ_ADR a0, s7, a1, 3
      li a1, 0x80103000
      ld a0, 0(a1)
      SC_CHECK_EQ_ADR a0, s9, a1, 4

# Evictions: store to five lines in the same set (4 KiB apart), one more than the four ways, each line
# holding its own address, then read them back.  Lines are evicted and refetched along the way.
      li a1, 0x80104000
      li a2, 0x1000
      li a3, 5
1:
      sd a1, 0(a1)
      add a1, a1, a2
      addi a3, a3, -1
      bnez a3, 1b
      li a1, 0x80104000
      li a3, 5
2:
      ld a0, 0(a1)
      SC_CHECK_EQ_ADR a0, a1, a1, 5
      add a1, a1, a2
      addi a3, a3, -1
      bnez a3, 2b

      SC_PASS
      j done
